"use strict";
const $=id=>document.getElementById(id), T=AfterGridTheme, root=document.documentElement;
const system=matchMedia("(prefers-color-scheme: dark)");
const defaultPrefs={theme:"overwatch",mode:"dark",density:"comfortable",motion:false,favorites:[]};
let prefs={...defaultPrefs}, workspace="admin", page="overview", step=0, selected=new Set(), installed=new Set(["knowledge","maps","communications","supplies","notes"]), activity=["Example: Knowledge archive indexed","Example: Backup verification completed"];
try{const saved=JSON.parse(localStorage.getItem("aftergrid-ui-prototype-v1")||"null");if(saved&&typeof saved==="object"){prefs={theme:T.builtins.some(t=>t.id===saved.theme)?saved.theme:defaultPrefs.theme,mode:["light","dark","system"].includes(saved.mode)?saved.mode:defaultPrefs.mode,density:saved.density==="compact"?"compact":"comfortable",motion:saved.motion===true,favorites:Array.isArray(saved.favorites)?saved.favorites.filter(x=>typeof x==="string").slice(0,20):[]};}}catch{}
const paths={overview:"M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z",knowledge:"M3 4l9 3 9-3v15l-9 3-9-3z M12 7v15",maps:"M3 5l6-3 6 4 6-3v16l-6 3-6-4-6 3z M9 2v16 M15 6v16",communications:"M5 8h14v13H5z M9 8l7-6 M8 12h8 M8 16h8",supplies:"M3 6l9-4 9 4v12l-9 4-9-4z M3 6l9 5 9-5 M12 11v11",education:"M2 8l10-5 10 5-10 5z M5 10v7l7 4 7-4v-7",notes:"M5 3h14v18H5z M8 7h8 M8 11h8 M8 15h6",media:"M3 4h18v16H3z M10 8l6 4-6 4z",plans:"M6 4h12v17H6z M9 2h6v4H9z M9 10h6 M9 14h6",applications:"M4 4h16v16H4z M4 12h16 M12 4v16",content:"M12 3v13 M7 11l5 5 5-5 M4 17v4h16v-4",updates:"M20 8a8 8 0 1 0 0 8 M20 3v5h-5",backup:"M12 2l9 4v6c0 5-5 9-9 10-4-1-9-5-9-10V6z M8 12l3 3 5-6",appearance:"M12 3a9 9 0 1 0 0 18h2a2 2 0 0 0 0-4h-1a1 1 0 0 1 0-2h5a3 3 0 0 0 3-3 9 9 0 0 0-9-9z M7 8h.1 M12 6h.1 M17 8h.1",setup:"M4 5h16v14H4z M8 9h8 M8 13h8",activity:"M2 12h5l3-7 4 14 3-7h5"};
function icon(id){return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="'+(paths[id]||paths.overview)+'"/></svg>';}
const tools=[["knowledge","Knowledge library","Kiwix","Read offline guides and reference material."],["maps","Maps & navigation","MapLibre / Valhalla","Explore local maps and plan routes."],["communications","Communications","MeshMonitor","Mesh networks and manual device checks."],["supplies","Food & supplies","Grocy / Homebox","Track food, equipment and recipes."],["education","Education","Kolibri","Offline lessons and learning resources."],["notes","Notes & documents","DokuWiki","Shared documents and local references."],["media","Media library","Jellyfin","Access locally stored media."],["plans","Emergency plans","AfterGrid","Review shared PACE plans."]];
const adminNav=[["overview","Overview"],["applications","Applications"],["content","Content & maps"],["supplies","Households & inventory"],["updates","Updates"],["backup","Backup & recovery"],["activity","Activity"],["setup","Setup wizard"],["appearance","Appearance"]];
const homeNav=[["home","Home"],...tools.map(t=>[t[0],t[1]]),["appearance","Appearance"]];
function persist(){try{localStorage.setItem("aftergrid-ui-prototype-v1",JSON.stringify(prefs));}catch{}}
function apply(){T.apply(root,T.resolve(prefs.theme,prefs.mode,system.matches));root.dataset.density=prefs.density;root.dataset.motion=prefs.motion?"reduced":"normal";persist();}
function go(id){if(id==="home"){workspace="home";}if(page===id&&location.hash==="#"+id){render();return;}location.hash=id;}
function readRoute(){const id=location.hash.slice(1);if(id==="home")workspace="home";const allowed=(workspace==="home"?homeNav:adminNav).some(n=>n[0]===id)||(workspace==="admin"&&id.startsWith("app-")&&tools.some(t=>t[0]===id.slice(4)&&t[0]!=="plans"));page=allowed?id:workspace==="home"?"home":"overview";render();}
function nav(){const items=workspace==="home"?homeNav:adminNav;$("workspace").value=workspace;$("navigation").innerHTML=items.map(([id,name])=>'<a class="nav-item" href="#'+id+'" '+((id===page||id==="applications"&&page.startsWith("app-"))?'aria-current="page"':'')+'>'+icon(id)+name+'</a>').join("");$("breadcrumb").textContent=(workspace==="home"?"Household":"Administration")+" / "+(page.startsWith("app-")?"Application details":(items.find(n=>n[0]===page)||items[0])[1]);}
function heading(title,description){return '<div class="page-heading"><div><div class="eyebrow">'+(workspace==="home"?"Household workspace":"Administration workspace")+'</div><h1>'+title+'</h1><p>'+description+'</p></div></div>';}
function tile(t,catalog=false){const [id,name,upstream,desc]=t;const available=installed.has(id)||id==="plans";const favorite=prefs.favorites.includes(id);return '<article class="tile"><div class="tile-top"><div class="tile-icon">'+icon(id)+'</div>'+(catalog?'<span class="status">'+(available?"Installed":"Optional")+'</span>':'<button class="favorite" data-favorite="'+id+'" aria-label="Favorite '+name+'" aria-pressed="'+favorite+'">'+(favorite?"★":"☆")+'</button>')+'</div><h3>'+name+'</h3><small>'+upstream+'</small><p>'+desc+'</p><button class="tile-action" data-'+(catalog?"app":"open")+'="'+id+'">'+(catalog?"View details": "Open preview")+' <span aria-hidden="true">›</span></button></article>';}
function tileGrid(items,catalog=false){return '<div class="grid">'+(items.length?items.map(t=>tile(t,catalog)).join(""):'<p>No matching tools.</p>')+'</div>';}
function metric(label,value,note){return '<article class="metric"><small>'+label+'</small><strong>'+value+'</strong><small>'+note+'</small></article>';}
function list(items){return '<ul class="list">'+items.map(([a,b])=>'<li><span>'+a+'</span><span class="status">'+b+'</span></li>').join("")+'</ul>';}
function panel(title,body){return '<section class="panel stack"><h2>'+title+'</h2>'+body+'</section>';}
function overview(){return '<section class="hero"><div class="eyebrow">Local resource system / design preview</div><h1>Life beyond the grid.</h1><p>One place for knowledge, navigation, communications and household resources.</p></section><div class="grid metrics">'+metric("Applications",installed.size+" installed","Example catalog state")+metric("Offline content","124 GB","Example archive size")+metric("Storage used","42%","Example capacity")+'</div><div class="section-heading"><h2>Quick access</h2><button class="quiet" data-page="applications">All applications</button></div>'+tileGrid(tools.filter(t=>installed.has(t[0])).slice(0,4),true)+'<div class="split">'+panel("Readiness indicators",'<p>Illustrative presence indicators; not a readiness certification.</p>'+list([["Knowledge archives","Example indexed"],["Regional maps","Example present"],["PACE plans","Example saved"],["Physical offline test","Not performed"]]))+panel("Recent activity",list(activity.slice(0,4).map(x=>[x,"Demo"])))+'</div>';}
function home(){const available=tools.filter(t=>installed.has(t[0])||t[0]==="plans");return '<section class="hero"><div class="eyebrow">Your local resources</div><h1>Life beyond the grid.</h1><p>Find the tools and information available to your household.</p></section><div class="filterbar"><input id="tool-search" aria-label="Search tools" placeholder="Find a tool..." type="search"></div><div id="tool-results">'+tileGrid(available.sort((a,b)=>Number(prefs.favorites.includes(b[0]))-Number(prefs.favorites.includes(a[0]))))+'</div>';}
function catalog(){return heading("Applications","Discover and manage optional services. Nothing is installed from this prototype.")+'<div class="filterbar"><input id="tool-search" type="search" aria-label="Search catalog" placeholder="Search applications"><select id="catalog-filter" aria-label="Filter catalog"><option value="">All applications</option><option value="installed">Installed</option><option value="optional">Optional</option></select></div><div id="tool-results">'+tileGrid(tools.filter(t=>t[0]!=="plans"),true)+'</div>';}
function appDetails(id){const t=tools.find(x=>x[0]===id);const has=installed.has(id);return heading(t[1],t[3])+panel("Application details",list([["Native application",t[2]],["Catalog state",has?"Example installed":"Optional"],["Actual readiness","Not connected"],["Storage and native access","Review on live installation"],["Backup coverage","Not verified"]])+'<div class="actions"><button data-install-demo="'+id+'">'+(has?"Simulate removal":"Simulate installation")+'</button><button class="quiet" data-page="applications">Back to catalog</button></div><p>Real removal must retain application data by default. This preview changes only temporary example state.</p>');}
function filterTiles(){const q=$("tool-search").value.toLowerCase();const isCatalog=page==="applications";const status=$("catalog-filter")?.value||"";let items=tools.filter(t=>(isCatalog?t[0]!=="plans":installed.has(t[0])||t[0]==="plans")&&t.join(" ").toLowerCase().includes(q)&&(!status||(status==="installed"?installed.has(t[0]):!installed.has(t[0]))));if(!isCatalog)items.sort((a,b)=>Number(prefs.favorites.includes(b[0]))-Number(prefs.favorites.includes(a[0])));$("tool-results").innerHTML=tileGrid(items,isCatalog);}
function appearance(){const theme=T.resolve(prefs.theme,prefs.mode,system.matches).theme;return heading("Appearance","Choose your theme and layout. Preferences stay in this browser.")+panel("Theme",'<div class="theme-options">'+T.builtins.map(t=>'<button class="theme-choice quiet" data-theme-choice="'+t.id+'" aria-pressed="'+(t.id===theme.id)+'"><span class="swatches">'+[t.dark.bg,t.dark.panel,t.dark.accent,t.light.bg].map(c=>'<span style="background:'+c+'"></span>').join("")+'</span><strong>'+t.name+'</strong><small>'+t.description+'</small></button>').join("")+'</div>')+panel("Display preferences",'<div class="field"><label for="mode">Color mode</label><select id="mode"><option value="system">Follow system</option><option value="light">Light</option><option value="dark">Dark</option></select></div><div class="field"><label for="density">Density</label><select id="density"><option value="comfortable">Comfortable</option><option value="compact">Compact</option></select></div><label class="check"><input type="checkbox" id="motion"> Reduce motion</label><div class="actions"><button class="quiet" id="reset">Reset appearance</button></div><p>Community imports are planned; this preview uses only the four bundled theme manifests.</p>');}
function mapPreview(){return '<div class="map-demo"><svg viewBox="0 0 600 240" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><g fill="none" stroke="currentColor" opacity=".2">'+Array.from({length:12},(_,i)=>'<path d="M-40 '+(i*25)+' Q160 '+(i*25-80)+' 300 '+(i*25+8)+' T640 '+(i*25-30)+'"/>').join("")+'</g><path d="M80 180 150 140 270 158 330 75 495 48" stroke="currentColor" stroke-width="4" fill="none" stroke-dasharray="8 5"/><g fill="currentColor"><circle cx="80" cy="180" r="7"/><circle cx="495" cy="48" r="7"/></g></svg><span class="map-caption">Decorative route preview · not navigation data</span></div>';}
function resource(id){const t=tools.find(x=>x[0]===id);return heading(t?.[1]||"Resource",t?.[3]||"Illustrative resource page.")+(id==="maps"?mapPreview():"")+panel("Local resources",'<p>This is a layout concept. Native applications and server APIs are not connected.</p>'+list([[t?.[2]||"AfterGrid","Example resource"],["Availability","Not verified"]]))+'<div class="actions"><button class="quiet" data-page="'+(workspace==="home"?"home":"overview")+'">Back to dashboard</button></div>';}
function sectionPage(id){const config={content:["Content & maps","Manage local downloads and datasets.",[["Knowledge archives","Example 124 GB"],["Regional maps","Example 3 regions"],["Routing graph","Not verified"]]],supplies:["Households & inventory","Separate ownership and physical storage.",[["Homebox","Native access required"],["Grocy","Native access required"],["Consolidated report","No live data"]]],updates:["Updates","Reviewed releases and independent application updates.",[["AfterGrid core","Activation not connected"],["Applications","Review required"]]],backup:["Backup & recovery","Review snapshot coverage and verification separately.",[["Repository","Example connected"],["Last snapshot","Example completed"],["Restore verification","Not performed"]]],activity:["Activity","Persistent job and operation history.",activity.map(x=>[x,"Demo"])]};const c=config[id];return heading(c[0],c[1])+panel("Overview",list(c[2])+(id==="content"?mapPreview():"")+(["content","updates","backup"].includes(id)?'<div class="actions"><button data-demo="'+id+'">Preview confirmation</button></div>':""));}
function wizard(){const stages=["Welcome","Choose applications","Review selection","Installation","Ready"];let body="";if(step===0)body='<p>Welcome to the AfterGrid setup preview. In the real portal, a local administrator is created before optional applications are selected. No credentials are collected here.</p>';if(step===1)body='<p>Nothing is selected by default. You can skip all optional applications.</p>'+tools.filter(t=>t[0]!=="plans").map(t=>'<label class="check"><input type="checkbox" data-select="'+t[0]+'" '+(selected.has(t[0])?"checked":"")+'>'+t[1]+'</label>').join("");if(step===2)body='<p>Review your example selection. No real storage or dependency checks have been run.</p>'+list(selected.size?[...selected].map(id=>[tools.find(t=>t[0]===id)[1],"Selected"]):[["Core only","No optional apps"]]);if(step===3)body='<p>Simulated installation summary — no containers are downloaded or started.</p>'+list(selected.size?[...selected].map(id=>[tools.find(t=>t[0]===id)[1],"Example complete"]):[["Core","Example ready"]]);if(step===4)body='<p>Your design preview is ready. The real setup must retain native account setup, explicit sharing and actual readiness checks.</p>';return heading("First-run setup","Interactive five-stage design preview.")+'<div class="stepbar" aria-label="Step '+(step+1)+' of 5">'+stages.map((s,i)=>'<span class="'+(i<=step?"done":"")+'"></span>').join("")+'</div>'+panel((step+1)+". "+stages[step],body+'<div class="actions">'+(step>0?'<button class="quiet" data-step="back">Back</button>':'')+(step<4?'<button data-step="next">'+(step===2?"Simulate installation":"Continue")+'</button>':'<button data-page="overview">Open dashboard</button>')+(step===1?'<button class="quiet" data-step="skip">Skip optional apps</button>':'')+'</div>');}
function render(){nav();$("page").innerHTML=page==="overview"?overview():page==="home"?home():page==="applications"?catalog():page.startsWith("app-")?appDetails(page.slice(4)):page==="appearance"?appearance():page==="setup"?wizard():workspace==="admin"&&["content","supplies","updates","backup","activity"].includes(page)?sectionPage(page):resource(page);if(page==="appearance"){$("mode").value=prefs.mode;$("density").value=prefs.density;$("motion").checked=prefs.motion;}document.title="AfterGrid | "+(document.querySelector("#page h1")?.textContent||"Design preview");}
let dialogAction=null,returnFocus=null;
function confirmDemo(title,desc,callback){returnFocus=document.activeElement;dialogAction=callback;$("dialog-title").textContent=title;$("dialog-description").textContent=desc;$("confirmation").showModal();}
$("dialog-cancel").addEventListener("click",()=>$("confirmation").close("cancel"));
$("dialog-confirm").addEventListener("click",()=>$("confirmation").close("confirm"));
$("confirmation").addEventListener("close",()=>{const action=dialogAction;dialogAction=null;if($("confirmation").returnValue==="confirm"&&action)action();if(returnFocus?.isConnected)returnFocus.focus();else $("main").focus();returnFocus=null;});
$("confirmation").addEventListener("cancel",e=>{e.preventDefault();$("confirmation").close("cancel");});
$("workspace").addEventListener("change",e=>{workspace=e.target.value;go(workspace==="home"?"home":"overview");});
$("menu").addEventListener("click",()=>{const open=document.querySelector(".shell").classList.toggle("menu-open");$("menu").setAttribute("aria-expanded",String(open));});
$("navigation").addEventListener("click",e=>{if(e.target.closest("a")){document.querySelector(".shell").classList.remove("menu-open");$("menu").setAttribute("aria-expanded","false");}});
$("appearance-shortcut").addEventListener("click",()=>go("appearance"));
$("page").addEventListener("input",e=>{if(e.target.id==="tool-search")filterTiles();});
$("page").addEventListener("change",e=>{const t=e.target;if(t.id==="catalog-filter")filterTiles();else if(t.id==="mode"){prefs.mode=t.value;apply();}else if(t.id==="density"){prefs.density=t.value;apply();}else if(t.id==="motion"){prefs.motion=t.checked;apply();}else if(t.dataset.select){if(t.checked)selected.add(t.dataset.select);else selected.delete(t.dataset.select);}});
$("page").addEventListener("click",e=>{const b=e.target.closest("button");if(!b)return;const d=b.dataset;if(d.page){go(d.page);}else if(d.themeChoice){prefs.theme=d.themeChoice;apply();render();document.querySelector('[data-theme-choice="'+prefs.theme+'"]').focus();}else if(d.favorite){const id=d.favorite;prefs.favorites=prefs.favorites.includes(id)?prefs.favorites.filter(x=>x!==id):[...prefs.favorites,id];persist();filterTiles();document.querySelector('[data-favorite="'+id+'"]')?.focus();}else if(d.open){go(d.open);}else if(d.app){go("app-"+d.app);}else if(d.installDemo){const t=tools.find(x=>x[0]===d.installDemo);if(!t)return;const has=installed.has(t[0]);confirmDemo(t[1],(has?"Simulate removing the application from the example catalog.":"Simulate adding the application to the example catalog.")+" No real services or data will change.",()=>{if(has)installed.delete(t[0]);else installed.add(t[0]);activity.unshift("Example: "+t[1]+(has?" removed":" installed"));render();});}else if(d.demo){confirmDemo("Preview "+d.demo+" operation","This demonstrates a confirmation dialog only. No requests, snapshots, downloads or updates will be executed.",()=>{activity.unshift("Example: "+d.demo+" confirmation");});}else if(d.step){if(d.step==="skip"){selected.clear();step=2;}else if(d.step==="next")step=Math.min(4,step+1);else step=Math.max(0,step-1);render();$("main").focus();}else if(b.id==="reset"){prefs={...defaultPrefs,favorites:prefs.favorites};apply();render();$("reset").focus();}});
system.addEventListener("change",()=>{if(prefs.mode==="system")apply();});
window.addEventListener("hashchange",()=>{readRoute();$("main").focus();});
apply();readRoute();
